def topic(id, slug, title, objective, start, end, issue, remediation, visual, sections, recall_items, worked_problem, worked_steps, focused, mastery):
    return {
        "id": id, "slug": slug, "title": title, "objective": objective,
        "chunks": list(range(start, end + 1)), "signal": issue,
        "remediation": remediation, "visual": visual, "sections": sections,
        "recall": recall_items, "worked": worked_problem, "worked_steps": worked_steps,
        "focused": focused, "mastery": mastery,
    }


