def quiz(topic_data, kind):
    questions = []
    tier = "easy" if kind == "focused-practice" else "hard"
    dimensions = ["representationTransfer", "auxiliaryTechnique"] if tier == "easy" else ["representationTransfer", "modelOrDerivation", "methodSelection"]
    for i, (prompt, choices, answer, solution) in enumerate(topic_data["focused" if kind == "focused-practice" else "mastery"], 1):
        options = [{"id": "a", "text": choices[0]}]
        for j, choice in enumerate(choices[1:], 1):
            options.append({"id": chr(97 + j), "text": choice, "issueSignals": signal(topic_data["signal"] if j < 3 else "sign-error")})
        questions.append({"id": f"q{i:03d}", "type": "multipleChoice", "prompt": prompt, "choices": options,
                          "answer": {"choiceId": "a"}, "issueSignals": signal(topic_data["signal"]),
                          "difficultyDimensions": dimensions, "difficultyEvidence": "Requires matching a vector-calculus representation to the governing relation and orientation.",
                          "explanation": expl(solution, topic_data["remediation"], prompt, answer,
                                              [(option["id"], option["text"]) for option in options[1:]])})
    goal, activity = ("practice", "focusedPractice") if kind == "focused-practice" else ("evaluate", "masteryCheck")
    return {"schemaVersion": 1, "id": f"{topic_data['slug']}-{kind}-s2c", "title": f"{topic_data['title']}: {'Focused Practice' if kind == 'focused-practice' else 'Mastery Check'}", "assessmentType": "quiz", "categoryId": "calculus-3", "topicId": topic_data["id"], "modeDefault": "practice", "randomizeQuestions": True, "skills": [topic_data["slug"]], "navigation": {"learningGoal": goal, "activityType": activity, "tags": ["calculus-3", topic_data["id"], topic_data["slug"], kind]}, "authoring": {"sourcePacketId": f"packet-calc3-{topic_data['slug']}-v1", "difficultyTier": tier, "visualRequirement": "required", "visualRationale": "Questions reinforce the topic's original vector-calculus representation.", "exceptionReason": "Four distinct source-grounded items form this focused bank."}, "questions": questions}


def blueprint(topic_data, kind):
    tier = "easy" if kind == "focused-practice" else "hard"
    dimensions = ["representationTransfer", "auxiliaryTechnique"] if tier == "easy" else ["representationTransfer", "modelOrDerivation", "methodSelection"]
    bank = topic_data["focused" if kind == "focused-practice" else "mastery"]
    return {"schemaVersion": 1, "assessmentId": f"{topic_data['slug']}-{kind}-s2c", "categoryId": "calculus-3", "topicId": topic_data["id"], "sourceId": SOURCE, "packetId": f"packet-calc3-{topic_data['slug']}-v1", "reviewState": "approved", "blueprints": [{"questionId": f"q{i:03d}", "objectiveId": topic_data["objective"], "sourceChunks": [f"chunk-{topic_data['chunks'][0]:04d}"], "questionType": "multipleChoice", "givens": question[0], "unknown": "Select the mathematically valid conclusion.", "representationRequirement": f"Original {topic_data['visual']} visual when spatial orientation is relevant.", "governingPrinciple": topic_data["sections"][0][0], "methodSteps": ["Identify the field, curve, surface, or region.", "Apply the governing relation.", "Check direction, orientation, and result type."], "likelyMisconception": "Using a familiar theorem or orientation with the wrong geometric object.", "issueSignal": topic_data["signal"], "verificationMethod": "Independent component calculation, integral evaluation, or orientation check.", "difficultyTier": tier, "difficultyDimensions": dimensions, "subjectDifficultyTags": ["representation", "orientation"], "difficultyEvidence": "Requires selecting the correct vector-calculus relation and checking its geometry.", "prerequisiteObjectives": ["calc3-ready-prior-skills"], "extensionObjectives": [topic_data["objective"]], "semanticVariationAxes": ["representation", "unknown", "governing relation"], "reasoningSignature": f"{topic_data['slug']}-{kind}-{i}", "reviewState": "approved"} for i, question in enumerate(bank, 1)]}


def main():
    for data in TOPICS:
        for name, builder in [("concept-lesson", lesson), ("recall", recall), ("worked-example", worked)]:
            write_yaml(ASSESSMENTS / f"{data['slug']}-{name}-s2c.yaml", builder(data))
        for kind in ("focused-practice", "mastery-check"):
            write_yaml(ASSESSMENTS / f"{data['slug']}-{kind}-s2c.yaml", quiz(data, kind))
            write_yaml(BLUEPRINTS / f"{data['slug']}-{kind}-blueprints-s2c.yaml", blueprint(data, kind))
        (PACKETS / f"packet-calc3-{data['slug']}-v1.json").write_text(json.dumps(packet(data), indent=2) + "\n", encoding="utf-8")
        MEDIA.mkdir(parents=True, exist_ok=True)
        (MEDIA / f"{data['visual']}.svg").write_text(svg(data), encoding="utf-8")


if __name__ == "__main__":
    main()
